def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    def flood(stack,pred):
        comp=[]
        while stack:
            r,c=stack.pop()
            if r<0 or c<0 or r>=h or c>=w or seen[r][c] or not pred(g[r][c]): continue
            seen[r][c]=True; comp.append((r,c))
            stack+=[(r+1,c),(r-1,c),(r,c+1),(r,c-1)]
        return comp
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0,8) and not seen[r][c]:
                seed=flood([(r,c)],lambda v: v not in (0,8))
                rs=[p[0] for p in seed]; cs=[p[1] for p in seed]
                r0,c0=min(rs),min(cs); ph,pw=max(rs)-r0+1,max(cs)-c0+1
