def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=8 and not seen[r][c]:
                stack=[(r,c)]; comp=[]
                while stack:
                    rr,cc=stack.pop()
                    if rr<0 or cc<0 or rr>=h or cc>=w or seen[rr][cc] or g[rr][cc]==8: continue
                    seen[rr][cc]=True; comp.append((rr,cc))
                    stack+=[(rr+1,cc),(rr-1,cc),(rr,cc+1),(rr,cc-1)]
                nz=[p for p in comp if g[p[0]][p[1]]!=0]
                if not nz or len(comp)==len(nz): continue
                rs=[p[0] for p in nz]; cs=[p[1] for p in nz]
                r0,c0=min(rs),min(cs); ph,pw=max(rs)-r0+1,max(cs)-c0+1
                pat=[[g[r0+i][c0+j] for j in range(pw)] for i in range(ph)]
                for rr,cc in comp:
                    if g[rr][cc]==0:
                        out[rr][cc]=pat[(rr-r0)%ph][(cc-c0)%pw]
    return out

